-- Read-only deployment checks. No user rows, titles, keys or file contents are returned.
select n, item, ok from (values
 (1, 'user_books exists with RLS', coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.user_books')),false)),
 (2, 'user_book_adds exists with RLS', coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.user_book_adds')),false)),
 (3, 'all 10 book columns exist', (select count(*)=10 from information_schema.columns where table_schema='public' and table_name='user_books' and column_name in ('id','user_id','slot','title','page_count','size_bytes','file_path','status','created_at','updated_at'))),
 (4, 'one book per user and slot', exists(select 1 from pg_constraint where conrelid=to_regclass('public.user_books') and conname='user_books_one_per_slot' and contype='u' and convalidated)),
 (5, 'slots restricted to 1 and 2', exists(select 1 from pg_constraint where conrelid=to_regclass('public.user_books') and conname='user_books_slot_check' and contype='c' and convalidated)),
 (6, 'title restricted to 1..200 characters', exists(select 1 from pg_constraint where conrelid=to_regclass('public.user_books') and conname='user_books_title_check' and convalidated)),
 (7, 'page count restricted to 1..5000 or null', exists(select 1 from pg_constraint where conrelid=to_regclass('public.user_books') and conname='user_books_page_count_check' and convalidated)),
 (8, 'declared size restricted to 1..52428800', exists(select 1 from pg_constraint where conrelid=to_regclass('public.user_books') and conname='user_books_size_bytes_check' and convalidated)),
 (9, 'file path is bound to owner and book', exists(select 1 from pg_constraint where conrelid=to_regclass('public.user_books') and conname='user_books_own_path' and convalidated)),
 (10, 'uploading and ready status check', exists(select 1 from pg_constraint where conrelid=to_regclass('public.user_books') and conname='user_books_status_check' and convalidated)),
 (11, 'both owner foreign keys cascade from auth.users', (select count(*)=2 from pg_constraint where conrelid in (to_regclass('public.user_books'),to_regclass('public.user_book_adds')) and contype='f' and confrelid='auth.users'::regclass and confdeltype='c' and convalidated)),
 (12, 'both lookup indexes exist', to_regclass('public.user_books_user') is not null and to_regclass('public.user_book_adds_recent') is not null),
 (13, 'all four enabled book triggers exist', (select count(*)=4 from pg_trigger where tgrelid=to_regclass('public.user_books') and not tgisinternal and tgenabled<>'D' and tgname in ('user_books_updated_at','user_books_fixed','user_books_count','user_books_file_removed'))),
 (14, 'all four feature functions exist', (select count(*)=4 from pg_proc where pronamespace='public'::regnamespace and proname in ('user_books_fixed_columns','user_books_count_add','user_books_require_file_removed','user_books_lock_file'))),
 (15, 'rate limit is ten in 24 hours with a per-user lock', exists(select 1 from pg_proc where oid=to_regprocedure('public.user_books_count_add()') and prosrc like '%pg_advisory_xact_lock%' and prosrc like '%24 hours%' and prosrc like '%>= 10%' and prosrc like '%2 days%' and prosrc like '%distinct from auth.uid()%')),
 (16, 'immutable fields include book id', exists(select 1 from pg_proc where oid=to_regprocedure('public.user_books_fixed_columns()') and prosrc like '%new.id is distinct from old.id%' and prosrc like '%new.size_bytes is distinct from old.size_bytes%' and prosrc like '%new.created_at is distinct from old.created_at%')),
 (17, 'file deletion guard checks Storage before freeing a slot', exists(select 1 from pg_proc where oid=to_regprocedure('public.user_books_require_file_removed()') and prosecdef and prosrc like '%storage.objects%' and prosrc like '%user_book_file_must_be_removed_first%')),
 (18, 'Storage write helper locks only an owned book', exists(select 1 from pg_proc where oid=to_regprocedure('public.user_books_lock_file(text)') and prosecdef and provolatile='v' and prosrc like '%b.user_id = v_user%' and prosrc like '%for update%')),
 (19, 'private user-books bucket: PDF only, 50 MiB', exists(select 1 from storage.buckets where id='user-books' and not public and file_size_limit=52428800 and allowed_mime_types=array['application/pdf']::text[])),
 (20, 'four owner-only book policies exist', (select count(*)=4 from pg_policies where schemaname='public' and tablename='user_books' and policyname in ('readers see their own books','readers add their own books','readers change their own books','readers delete their own books') and roles=array['authenticated']::name[])),
 (21, 'rate history has only an owner read policy', (select count(*)=1 and bool_and(cmd='SELECT' and roles=array['authenticated']::name[]) from pg_policies where schemaname='public' and tablename='user_book_adds')),
 (22, 'Storage insert uses the write lock', exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='readers upload their own book files' and cmd='INSERT' and with_check like '%user_books_lock_file%')),
 (23, 'Storage replacement uses the write lock', exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='readers replace their own book files' and cmd='UPDATE' and with_check like '%user_books_lock_file%')),
 (24, 'Storage read and delete policies exist', (select count(*)=2 from pg_policies where schemaname='storage' and tablename='objects' and policyname in ('readers open their own book files','readers delete their own book files') and roles=array['authenticated']::name[])),
 (25, 'reader has book CRUD but no TRUNCATE', has_table_privilege('authenticated','public.user_books','SELECT') and has_table_privilege('authenticated','public.user_books','INSERT') and has_table_privilege('authenticated','public.user_books','UPDATE') and has_table_privilege('authenticated','public.user_books','DELETE') and not has_table_privilege('authenticated','public.user_books','TRUNCATE')),
 (26, 'reader has read-only rate history', has_table_privilege('authenticated','public.user_book_adds','SELECT') and not has_table_privilege('authenticated','public.user_book_adds','INSERT,UPDATE,DELETE,TRUNCATE')),
 (27, 'anonymous has no private table access', not has_table_privilege('anon','public.user_books','SELECT,INSERT,UPDATE,DELETE,TRUNCATE') and not has_table_privilege('anon','public.user_book_adds','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),
 (28, 'only signed-in readers may invoke the write helper', has_function_privilege('authenticated','public.user_books_lock_file(text)','EXECUTE') and not has_function_privilege('anon','public.user_books_lock_file(text)','EXECUTE')),
 (29, 'trigger functions cannot be called by API clients', not has_function_privilege('authenticated','public.user_books_fixed_columns()','EXECUTE') and not has_function_privilege('authenticated','public.user_books_count_add()','EXECUTE') and not has_function_privilege('authenticated','public.user_books_require_file_removed()','EXECUTE')),
 (30, 'Storage enforces one current file per bucket and filename', exists(select 1 from pg_index i where i.indrelid='storage.objects'::regclass and i.indisunique and i.indisvalid and i.indnkeyatts=2 and (select array_agg(a.attname order by a.attname) from unnest(i.indkey) with ordinality k(attnum,ord) join pg_attribute a on a.attrelid=i.indrelid and a.attnum=k.attnum where k.ord<=i.indnkeyatts)=array['bucket_id','name']::name[] and (i.indpred is null or pg_get_expr(i.indpred,i.indrelid)='(archived_at IS NULL)'))),
 (31, 'private PDFs have versioning disabled', exists(select 1 from storage.buckets where id='user-books' and versioning_status='DISABLED'))
) as checks(n,item,ok) order by n;
